// @generated by:gauntlet run:godseye-local-delivery
import { randomUUID } from "node:crypto";
import type { CreateDeliveryPolicyInput } from "@godseye/contracts";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  createDeliveryPolicy,
  revokeDeliveryPolicy,
} from "../packages/core/src/delivery-policy.js";
import {
  type DeliveryState,
  deliveryPolicyFor,
  validateDeliveryPolicy,
} from "../packages/core/src/delivery-state.js";
import { owner, repository } from "./helpers.js";
import { type InfrastructureFixture, infrastructureFixture } from "./infra-helpers.js";

describe("fresh exact-scope standing delivery policy authority", () => {
  let fixture: InfrastructureFixture, state: DeliveryState, input: CreateDeliveryPolicyInput;
  beforeEach(async () => {
    fixture = await infrastructureFixture();
    const project = await fixture.core.configureRepository(
      owner,
      fixture.project.id,
      repository,
      fixture.project.revision,
      randomUUID(),
    );
    state = {
      store: fixture.store,
      now: fixture.clock.now,
      foundation: fixture.infrastructure.foundation,
    };
    input = {
      projectId: project.id,
      environmentId: fixture.development.id,
      expectedProjectRevision: project.revision,
      expectedEnvironmentRevision: fixture.development.revision,
      recipe: { kind: "static", context: "." },
      requiredChecks: ["test"],
      maxArtifactMiB: 16,
      maxConcurrentPreviews: 2,
      previewTtlHours: 24,
      limits: { cpuMilliCores: 500, memoryMiB: 128, storageGiB: 1, pids: 32 },
      autoDeploy: true,
      expiresAt: new Date(fixture.clock.now().getTime() + 7 * 86_400_000).toISOString(),
    };
  });
  afterEach(async () => {
    await fixture.store.close();
  });

  it("T-AC-45 binds a fresh owner's policy to server-owned numeric source and target snapshots", async () => {
    const policy = await createDeliveryPolicy(state, fixture.freshOwner(), input, randomUUID());
    expect(policy).toMatchObject({
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
      repository,
      revision: 0,
      revokedAt: null,
    });
    expect(policy.hash).toMatch(/^[a-f0-9]{64}$/);
    expect(await fixture.infrastructure.foundation.listRuns(owner)).toEqual([]);
  });
  it("T-AC-45 replays policy creation exactly once and rejects changed policy under a reused key", async () => {
    const key = randomUUID(),
      policy = await createDeliveryPolicy(state, fixture.freshOwner(), input, key);
    expect(await createDeliveryPolicy(state, fixture.freshOwner(), input, key)).toEqual(policy);
    await expect(
      createDeliveryPolicy(state, fixture.freshOwner(), { ...input, autoDeploy: false }, key),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
    expect(await fixture.store.db.select().from(schema.deliveryPolicies)).toHaveLength(1);
  });
  it.each(["service", "stale"])("T-AC-45 denies %s policy creation authority", async (mode) => {
    const actor =
      mode === "service"
        ? { id: "source-agent", kind: "service" as const, projectIds: [fixture.project.id] }
        : { ...fixture.freshOwner(), authenticatedAt: "2026-11-11T11:00:00.000Z" };
    await expect(createDeliveryPolicy(state, actor, input, randomUUID())).rejects.toMatchObject({
      status: 403,
    });
    expect(await fixture.store.db.select().from(schema.deliveryPolicies)).toEqual([]);
  });
  it.each([
    "expired",
    "beyond-thirty-days",
    "duplicate-checks",
    "stale-project",
    "stale-environment",
    "foreign-environment",
  ])("T-AC-45 rejects %s policy without recording authority", async (mode) => {
    const changed = structuredClone(input);
    if (mode === "expired") changed.expiresAt = fixture.clock.now().toISOString();
    if (mode === "beyond-thirty-days")
      changed.expiresAt = new Date(fixture.clock.now().getTime() + 31 * 86_400_000).toISOString();
    if (mode === "duplicate-checks") changed.requiredChecks = ["test", "test"];
    if (mode === "stale-project") changed.expectedProjectRevision += 1;
    if (mode === "stale-environment") changed.expectedEnvironmentRevision += 1;
    if (mode === "foreign-environment")
      changed.environmentId = fixture.secondProject.environments[0]?.id ?? randomUUID();
    await expect(
      createDeliveryPolicy(state, fixture.freshOwner(), changed, randomUUID()),
    ).rejects.toBeDefined();
    expect(await fixture.store.db.select().from(schema.deliveryPolicies)).toEqual([]);
  });
  it("T-AC-45 T-AC-47 cannot turn a recovery-held target into standing deployment authority", async () => {
    await fixture.store.db
      .update(schema.environments)
      .set({ kind: "recovery", recoveryHold: true })
      .where(eq(schema.environments.id, input.environmentId));
    await expect(
      createDeliveryPolicy(state, fixture.freshOwner(), input, randomUUID()),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
    expect(await fixture.store.db.select().from(schema.deliveryPolicies)).toEqual([]);
  });
  it("T-AC-45 does not treat the legacy repository auto-deploy preference as an existing standing policy", async () => {
    const project = await fixture.core.getProject(owner, fixture.project.id);
    await fixture.core.configureRepository(
      owner,
      project.id,
      { ...repository, autoDeploy: true },
      project.revision,
      randomUUID(),
    );
    expect(await fixture.store.db.select().from(schema.deliveryPolicies)).toEqual([]);
    expect(await fixture.infrastructure.foundation.listRuns(owner)).toEqual([]);
  });
  it("T-AC-45 revokes policy by exact revision and preserves durable replay history", async () => {
    const policy = await createDeliveryPolicy(state, fixture.freshOwner(), input, randomUUID()),
      key = randomUUID();
    const revoked = await revokeDeliveryPolicy(
      state,
      fixture.freshOwner(),
      policy.id,
      policy.revision,
      key,
    );
    expect(revoked).toMatchObject({
      id: policy.id,
      revision: 1,
      revokedAt: fixture.clock.now().toISOString(),
      hash: policy.hash,
    });
    expect(
      await revokeDeliveryPolicy(state, fixture.freshOwner(), policy.id, policy.revision, key),
    ).toEqual(revoked);
    await expect(validateDeliveryPolicy(state, fixture.store.db, policy.id)).rejects.toMatchObject({
      code: "POLICY_REVOKED",
    });
    await expect(
      revokeDeliveryPolicy(state, fixture.freshOwner(), policy.id, policy.revision, randomUUID()),
    ).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
  });
  it("T-AC-45 denies policy use after source binding changes without rewriting the original scope", async () => {
    const policy = await createDeliveryPolicy(state, fixture.freshOwner(), input, randomUUID()),
      project = await fixture.core.getProject(owner, fixture.project.id);
    await fixture.core.configureRepository(
      owner,
      project.id,
      { ...repository, installationId: repository.installationId + 1 },
      project.revision,
      randomUUID(),
    );
    await expect(validateDeliveryPolicy(state, fixture.store.db, policy.id)).rejects.toMatchObject({
      code: "POLICY_STALE",
    });
    expect((await deliveryPolicyFor(fixture.store.db, policy.id)).repository).toEqual(repository);
  });
  it("T-AC-49 retains narrow cleanup authority after policy revocation or expiry without permitting new delivery", async () => {
    const policy = await createDeliveryPolicy(state, fixture.freshOwner(), input, randomUUID());
    await revokeDeliveryPolicy(
      state,
      fixture.freshOwner(),
      policy.id,
      policy.revision,
      randomUUID(),
    );
    fixture.clock.advance(31 * 86_400_000);
    expect((await validateDeliveryPolicy(state, fixture.store.db, policy.id, true)).id).toBe(
      policy.id,
    );
    await expect(validateDeliveryPolicy(state, fixture.store.db, policy.id)).rejects.toMatchObject({
      code: "POLICY_REVOKED",
    });
  });
});
